-- Daily aura messages, season 1: 900 rows (60 per animal).
-- GENERATED by scripts/build-daily-aura-seed.js --update from supabase/content/daily-aura/season-1/.
-- Edit the JSON files and re-run the script; don't edit this file by hand.
--
-- Updates the rows that already exist for (aura_id, season, day_index) so they
-- match the JSON (every column). aura_id is looked up by animal name
-- (case-insensitive). Idempotent: safe to re-run.

begin;

update public.daily_aura_messages m
set message = v.message,
    do_text = v.do_text,
    dont_text = v.dont_text,
    action_text = v.action_text,
    action_why = v.action_why
from (values
  ('bear', 1, 'You can carry it alone. That doesn''t mean you should.', 'Ask for one small favor.', 'Say "I''m fine" on autopilot.', 'Ask one person for a small, specific favor.', 'People tend to like you more after helping you. A small ask builds closeness and takes some weight off you.'),
  ('bear', 2, 'Your patience is a superpower. Your silence is not a strategy.', 'Say the thing, calmly.', 'Go quiet for three days.', 'Raise one thing that''s bothering you, calmly, today.', 'Unspoken issues grow in your head and theirs. Said early and calmly, most of them take five minutes to solve.'),
  ('bear', 3, 'Hibernating isn''t healing. Come out of the cave for one coffee.', 'Text someone first.', 'Cancel because you''re cozy.', 'Text one friend and suggest coffee this week.', 'Isolation feels restful but drains your mood over time. One low-effort meetup is often enough to lift it.'),
  ('bear', 4, 'Stubborn and right are different words. Check which one you are today.', 'Hear one counterargument.', 'Dig in out of habit.', 'Ask someone to explain the view you disagree with.', 'Hearing the other side out lowers both people''s defenses, and you either find a flaw or learn something.'),
  ('bear', 5, 'People lean on you because you never wobble. Wobble a little. It''s attractive.', 'Admit one doubt.', 'Fake total control.', 'Tell someone you trust about one thing you''re unsure of.', 'Showing a small doubt makes you more relatable, not weaker. People trust those who seem human.'),
  ('bear', 6, 'Your to-do list fears you. Your inbox, less so.', 'Clear three emails.', 'Reorganize the whole system.', 'Answer the three oldest emails in your inbox.', 'Small open loops keep tugging at your attention. Closing a few frees up more focus than their size suggests.'),
  ('bear', 7, 'You don''t need a crowd. You need two good people and a free evening.', 'Pick your two people.', 'Overbook your night.', 'Message your two favorite people and plan one evening.', 'Deep time with a few people does more for your mood than a crowded calendar with many.'),
  ('bear', 8, 'Being dependable is great. Being everyone''s backup plan is a job you never applied for.', 'Say no once.', 'Volunteer on reflex.', 'Say no to one request you''d normally take on.', 'Every automatic yes takes time from your own plans. One clear no resets what people expect from you.'),
  ('bear', 9, 'Slow and steady wins. Slow and silent just confuses people.', 'Send a quick status update.', 'Assume they know.', 'Send a two-line update on something you''re working on.', 'When people don''t hear from you, they fill the gap with worry. A short update saves everyone the guessing.'),
  ('bear', 10, 'Your growl works. Your soft voice works better today.', 'Lead with warmth.', 'Open with a complaint.', 'Start your next tough conversation with something kind.', 'People listen better when they don''t feel attacked. A warm opener keeps the other person open to your point.'),
  ('bear', 11, 'You''ve been strong for a while. Nobody is grading you on it.', 'Take a proper break.', 'Power through out of pride.', 'Take a real 30-minute break with no screens.', 'Rest isn''t a reward for being strong. Short, real breaks keep your energy up longer than pushing through.'),
  ('bear', 12, 'Someone wants to help and you keep blocking the door.', 'Accept the offer.', 'Say "I''ve got it" again.', 'Say yes the next time someone offers to help.', 'Accepting help builds the relationship and lets the other person feel useful. Both of you come out ahead.'),
  ('bear', 13, 'Today rewards the bear who finishes, not the bear who plans to finish.', 'Ship the half-done thing.', 'Polish it one more time.', 'Finish and send one task you''ve been polishing.', 'Done beats perfect. Extra polish past a point rarely changes the result, but finishing gives you momentum.'),
  ('bear', 14, 'Independence is great until it becomes a personality.', 'Team up on one task.', 'Quietly redo someone''s work.', 'Pair up with someone on one task today.', 'Working with others spreads the load and builds trust. And you get to see how other people solve problems.'),
  ('bear', 15, 'Your calm is contagious. Spread it where the chaos is.', 'Join the messy group chat.', 'Mute it and vanish.', 'Calmly help sort out one confusing thread or plan.', 'Calm spreads in groups just like stress does. One steady voice can settle a whole conversation.'),
  ('bear', 16, 'You''re not stubborn, you''re "consistent." Sure. Change one small thing anyway.', 'Try a new route home.', 'Order the usual.', 'Change one small part of your routine today.', 'A small novelty wakes up your attention and makes the day more memorable, at almost no cost.'),
  ('bear', 17, 'A strong presence doesn''t need to fill the room. Let someone else talk first.', 'Ask, then wait.', 'Finish their sentence.', 'Ask someone a question, then let them finish answering.', 'People feel respected when they get to finish. Waiting a beat before you answer often gets you better information.'),
  ('bear', 18, 'You guard your energy well. Don''t guard it from the people who give it back.', 'Call your favorite person.', 'Screen every call.', 'Call one person who always leaves you in a good mood.', 'Some people refill your energy instead of draining it. Making time for them is a smart way to recharge.'),
  ('bear', 19, 'The plan is solid. The plan is also allowed to change.', 'Leave one hour unplanned.', 'Panic when it shifts.', 'Leave one hour today with nothing planned.', 'Open time gives you room to adapt or rest. Plans with some slack in them break less when things change.'),
  ('bear', 20, 'You''re everyone''s rock. Even rocks get to sit down.', 'Delegate one thing.', 'Check it three times.', 'Hand one task to someone else and don''t check it.', 'Delegating frees up your time and shows trust. Checking it again quietly cancels both.'),
  ('bear', 21, 'Today, being reliable means showing up on time, not saving the day.', 'Do your part well.', 'Fix everyone else''s part.', 'Do your own part well and leave others'' parts to them.', 'Fixing other people''s work burns your energy and their motivation. Owning your share is what reliable looks like.'),
  ('bear', 22, 'You have strong opinions and stronger arms. Use neither in the group chat.', 'Reply with one calm line.', 'Write a paragraph at 1 a.m.', 'Reply to one tense message with a single calm line.', 'Long, heated replies usually escalate things. A short, calm answer cools things down and keeps you in control.'),
  ('bear', 23, 'Retreating to recharge is smart. Retreating to avoid is just hiding with a blanket.', 'Name what you''re avoiding.', 'Call it "me time" again.', 'Write down the one thing you''ve been avoiding.', 'Naming what you avoid makes it smaller and more concrete. A vague dread is harder to act on than a clear task.'),
  ('bear', 24, 'The thing you''ve been putting off takes 20 minutes. You''ve spent longer avoiding it.', 'Set a 20-minute timer.', 'Wait for the right mood.', 'Set a 20-minute timer and start the task you''re avoiding.', 'Starting is the hardest part. Once you begin, you usually want to finish, and the dread fades fast.'),
  ('bear', 25, 'Your quiet confidence is louder than you think. Use it for a request.', 'Ask for what you want.', 'Hint and hope.', 'Ask directly for one thing you want today.', 'People can''t respond to hints they miss. A clear request gets more yeses than you''d expect.'),
  ('bear', 26, 'You don''t owe anyone an explanation for needing space. Just a heads-up.', 'Say "back tomorrow."', 'Disappear without a word.', 'Before you go quiet, tell people when you''ll be back.', 'Time alone is fine. A short heads-up keeps people from reading your silence as a problem.'),
  ('bear', 27, 'Strength is also knowing when to drop the heavy thing.', 'Drop one obligation.', 'Carry it for appearances.', 'Drop one commitment you only keep for appearances.', 'Obligations you don''t care about drain energy you need for the ones you do. Letting one go is a trade, not a failure.'),
  ('bear', 28, 'You hold grudges like you hold doors: politely, and for too long.', 'Let one small thing go.', 'Re-read old messages.', 'Let go of one small grudge on purpose today.', 'Holding on to old irritations keeps the stress alive for you, not them. Letting go is mostly for your own peace.'),
  ('bear', 29, 'Someone admires you and is too shy to say it. Be approachable today.', 'Smile first.', 'Wear your busy face.', 'Smile and say hi first to someone you see often.', 'People often wait for a signal that you''re open to talking. A small greeting is an easy invitation.'),
  ('bear', 30, 'Your patience has limits. Today, tell people where they are.', 'Set one clear boundary.', 'Hit the limit in silence.', 'Tell one person clearly where your limit is.', 'People can''t respect a boundary they don''t know about. Stating it early avoids a bigger blow-up later.'),
  ('bear', 31, 'Routine is your armor. Leave one buckle undone.', 'Say yes to one plan.', 'Plan the spontaneity.', 'Say yes to one plan you''d normally skip.', 'Routine is comfortable, but a little novelty boosts mood and memory. One yes is enough to feel it.'),
  ('bear', 32, 'Being self-sufficient is great until you''re too proud to borrow a charger.', 'Ask for the small thing.', 'Make do out of pride.', 'Ask someone for a small thing instead of making do.', 'Small asks cost others very little and build connection. Making do out of pride only costs you.'),
  ('bear', 33, 'You''re the friend who remembers the plan. Today, be the friend who suggests one.', 'Propose a time and place.', 'Wait to be invited.', 'Suggest a time and place for a plan with friends.', 'Groups often stall because nobody decides. A concrete suggestion is usually all it takes to make it happen.'),
  ('bear', 34, 'Today''s power move: finishing early and not announcing it.', 'Close the laptop on time.', 'Invent extra work.', 'Close your laptop at your planned finish time.', 'Work tends to fill the time you give it. A firm stop protects your evening and keeps you sharper tomorrow.'),
  ('bear', 35, 'You can be gentle and firm at the same time. That''s your whole brand.', 'Say no kindly.', 'Say yes resentfully.', 'Say no kindly to one thing you don''t want to do.', 'A kind no keeps the relationship and your time intact. A resentful yes slowly damages both.'),
  ('bear', 36, 'Not every problem needs your paws on it. Some just need time.', 'Let one thing sort itself out.', 'Micromanage the outcome.', 'Pick one problem and give it a week before acting.', 'Many problems shrink or solve themselves with time. Waiting on purpose saves energy for the ones that won''t.'),
  ('bear', 37, 'Your loyalty is huge. Make sure it''s going to people who return it.', 'Invest in a mutual friend.', 'Chase the one-way one.', 'Do something kind for a friend who''s always there for you.', 'Investing in two-way friendships pays off. They''re the ones who will show up for you in return.'),
  ('bear', 38, 'The cave is comfy. The world is still out there. Pick a compromise.', 'Go for a short walk.', 'Doomscroll in bed.', 'Take a 15-minute walk outside.', 'A short walk boosts mood and clears your head. It''s an easy middle ground between hiding in and going all out.'),
  ('bear', 39, 'You''ve been carrying the team. Today, let the team notice.', 'Mention what you did.', 'Expect them to guess.', 'Tell your team one thing you did this week.', 'People rarely notice invisible work. Mentioning it isn''t bragging, it helps them know what you bring.'),
  ('bear', 40, 'You''re steady, not slow. Ignore anyone rushing you today.', 'Keep your own pace.', 'Rush to please someone.', 'Work at your own pace on one task today.', 'Rushing to please others leads to mistakes. A steady pace usually ends up both faster and better.'),
  ('bear', 41, 'Today asks for one honest sentence you''ve been rounding off.', 'Say it plainly.', 'Soften it into nothing.', 'Say one thing plainly that you usually soften.', 'Overly soft messages get misread or ignored. Clear words, said kindly, are easier for others to act on.'),
  ('bear', 42, 'Big bear energy: protect your time like it''s your favorite snack.', 'Block your calendar.', 'Accept every invite.', 'Block one hour in your calendar just for yourself.', 'Time that isn''t blocked gets taken by others. Putting it in the calendar makes it real and protected.'),
  ('bear', 43, 'You don''t need permission to rest. You barely need a reason.', 'Take the slow evening.', 'Justify it to anyone.', 'Plan a slow evening and don''t explain it to anyone.', 'Rest doesn''t need a reason. Justifying it turns a break into a debate and makes it less restful.'),
  ('bear', 44, 'Your silence reads as anger more often than you think. Add words.', 'Explain your mood briefly.', 'Let them guess.', 'Tell one person how you''re feeling in one sentence.', 'Silence is easy to misread as anger. A short explanation stops people from guessing the worst.'),
  ('bear', 45, 'You''d rather fix it yourself. Today, read the instructions first.', 'Ask how it works.', 'Wing it, then blame it.', 'Ask how something works before you try to fix it.', 'Asking first saves time and avoids mistakes. Even experts check the manual before they take things apart.'),
  ('bear', 46, 'Someone is waiting on your reply. They think it''s a test. It''s not, right?', 'Answer the pending message.', 'Let it age another day.', 'Reply to the message you''ve been leaving unanswered.', 'Unanswered messages make the other person worry and make you dread the reply. Sending it ends both.'),
  ('bear', 47, 'You''re a great listener. Today, try being a great talker.', 'Share one real update.', 'Say "nothing new."', 'Share one real update about your life with a friend.', 'People feel closer when you open up a little. Sharing invites them to share back.'),
  ('bear', 48, 'Changing your mind is allowed. It''s called new information.', 'Update your stance.', 'Defend the old take.', 'Say out loud that you''ve changed your mind on something.', 'Updating your view when you learn something new shows good judgment. People trust those who can admit it.'),
  ('bear', 49, 'Today''s luck favors the bear who leaves the house.', 'Say yes to an outing.', 'Find an excuse to stay in.', 'Say yes to one outing today.', 'Getting out brings small chances you''d never meet at home. Even a short trip can change the day''s mood.'),
  ('bear', 50, 'Responsibility looks good on you. Overresponsibility looks tired.', 'Hand back what isn''t yours.', 'Absorb someone''s mess.', 'Give back one task that isn''t yours to handle.', 'Taking on others'' responsibilities wears you out and stops them from learning. Handing it back helps both of you.'),
  ('bear', 51, 'You''re tougher than the problem. You''re also allowed to complain about it.', 'Vent to one friend.', 'Bottle it up.', 'Vent to one friend for ten minutes.', 'Putting frustration into words with someone you trust lowers stress. Bottling it up tends to make it stronger.'),
  ('bear', 52, 'You''re building something slowly. Slowly still counts.', 'Do one step today.', 'Compare your pace.', 'Take one small step on your long-term project.', 'Progress comes from steps repeated over time. Comparing your pace to others just steals energy from the next step.'),
  ('bear', 53, 'Be the calm one in a heated meeting. Then leave on time.', 'Lower the temperature.', 'Stay late to win it.', 'Lower the tension in one meeting, then leave on time.', 'A calm voice helps groups decide better. Leaving on time shows that calm isn''t the same as endless availability.'),
  ('bear', 54, 'Today, let someone surprise you instead of predicting them.', 'Give the benefit of the doubt.', 'Expect the worst.', 'Give one person the benefit of the doubt today.', 'Expecting the worst makes you read neutral things as negative. Assuming good intent often brings it out.'),
  ('bear', 55, 'You''re independent, not unreachable. Update your status accordingly.', 'Reply to one friend.', 'Leave everyone on read.', 'Reply to one friend you''ve left on read.', 'Being independent doesn''t mean being unreachable. A quick reply keeps friendships alive with very little effort.'),
  ('bear', 56, 'Your patience with others is legendary. Extend some to yourself.', 'Forgive your own mistake.', 'Replay it all night.', 'Forgive yourself for one mistake and move on.', 'Replaying mistakes rarely teaches you more. Treating yourself like a friend helps you recover and do better next time.'),
  ('bear', 57, 'Today, being stubborn about the right thing is the move.', 'Hold your boundary.', 'Hold a grudge instead.', 'Hold one boundary today without explaining it at length.', 'Long explanations invite debate. A short, steady no is easier for others to accept.'),
  ('bear', 58, 'You''re the one people call in a crisis. Call someone when there isn''t one.', 'Check in just because.', 'Only show up for drama.', 'Send a check-in message to someone, just because.', 'Reaching out when nothing is wrong builds trust. Then people know you care beyond the crisis moments.'),
  ('bear', 59, 'Strength is quiet. Kindness is quieter. Use both.', 'Do one silent favor.', 'Keep score.', 'Do one favor without telling anyone.', 'Quiet kindness lifts your own mood too. And it builds goodwill without turning into a scoreboard.'),
  ('bear', 60, 'The cave will still be there tonight. Go be seen for a bit.', 'Show up somewhere.', 'Leave after ten minutes.', 'Go somewhere people are and stay at least an hour.', 'Being seen helps people remember you and reach out. Staying a while gives real conversations time to start.'),
  ('cat', 1, 'You''re not aloof, you''re selective. Today, select someone.', 'Start one conversation.', 'Wait to be chased.', 'Start one conversation with someone you like.', 'People often assume others aren''t interested. Going first removes that doubt and is usually welcomed.'),
  ('cat', 2, 'Your curiosity is a gift. Your browser history is a cry for help.', 'Learn one thing deeply.', 'Open 20 rabbit holes.', 'Pick one topic and read about it for 30 minutes.', 'Jumping between tabs feels busy but sticks less. Focused time on one topic is how real knowledge builds up.'),
  ('cat', 3, 'You notice everything. Say one nice thing you noticed.', 'Give a specific compliment.', 'Keep the observation private.', 'Give one person a specific compliment.', 'Specific praise feels sincere and is remembered. It shows you pay attention, which people value a lot.'),
  ('cat', 4, 'Independence is cute. Ignoring a heartfelt text is not.', 'Reply with warmth.', 'Send a single "k."', 'Reply warmly to a message that meant something.', 'Short replies to heartfelt messages can feel like rejection. A few warm words show you received it.'),
  ('cat', 5, 'You land on your feet. That''s not a reason to keep jumping off things.', 'Think before the leap.', 'Test the drama for fun.', 'Wait one hour before acting on a big impulse.', 'A short pause lets the excitement settle so you can judge the choice clearly. Good ideas survive the wait.'),
  ('cat', 6, 'Being mysterious is fine. Being unreachable gets old fast.', 'Share one small plan.', 'Vanish for a week.', 'Tell one person what you''re up to this week.', 'Small updates keep people close without giving away much. Mystery is fun, but silence makes people drift.'),
  ('cat', 7, 'Today, knock one thing off the table that''s been bugging you.', 'Fix the small annoyance.', 'Live with it another month.', 'Fix one small annoyance you''ve been tolerating.', 'Small irritations drain attention every time you notice them. Fixing one often takes less time than you think.'),
  ('cat', 8, 'You choose your people carefully. Tell one of them they made the cut.', 'Say why you like them.', 'Assume they know.', 'Tell one friend why you''re glad they''re in your life.', 'People rarely know how much they matter to you. Saying it strengthens the bond more than you''d expect.'),
  ('cat', 9, 'Comfort zones are just sunbeams. Move to a new one.', 'Try a new café.', 'Sit in the same spot.', 'Work or relax somewhere new for an hour.', 'A new place sparks fresh thoughts and makes the day memorable. Novelty is a cheap way to lift your mood.'),
  ('cat', 10, 'Vulnerability isn''t a weakness. It''s just a belly you show on purpose.', 'Share one real feeling.', 'Deflect with sarcasm.', 'Share one honest feeling instead of a joke.', 'Opening up a little invites others to do the same. It''s how acquaintances turn into real friends.'),
  ('cat', 11, 'Your side-eye is a masterpiece. Don''t waste it on someone who''s trying.', 'Give them a fair chance.', 'Judge in the first minute.', 'Give someone who''s trying a fair second look.', 'First impressions are fast but often wrong. People who make an effort deserve a little more data.'),
  ('cat', 12, 'You adapt to anything. Except being told what to do. Today, take one tip.', 'Accept good advice.', 'Do the opposite to prove a point.', 'Take one piece of advice and try it today.', 'Good advice works the same no matter who gives it. Trying it is a low-cost test, not a surrender.'),
  ('cat', 13, 'You don''t need everyone to like you. You do need to call them back.', 'Return the missed call.', 'Let it go to voicemail again.', 'Call back the person you''ve been avoiding.', 'Delaying a call makes it feel heavier each day. Calling back takes minutes and clears the guilt.'),
  ('cat', 14, 'You''re comfortable alone. Today, be comfortable being invited.', 'Say yes to the invite.', 'Pretend you''re busy.', 'Accept the next invite you get.', 'Saying yes keeps you on people''s lists. Turning down invites too often makes them stop asking.'),
  ('cat', 15, 'Nine lives, one calendar. Pick what matters.', 'Say no to one thing.', 'Spread yourself thin.', 'Cancel or decline one thing that doesn''t matter to you.', 'Your time and energy are limited. Cutting one low-value plan makes room for what you care about.'),
  ('cat', 16, 'Your instinct for people is sharp. Trust it on the first impression today.', 'Trust the vibe check.', 'Overrule your gut.', 'Act on your first impression of someone today.', 'Quick reads of people are often surprisingly accurate. Overthinking can hide what you already noticed.'),
  ('cat', 17, 'Curiosity is your engine. Finishing is your missing gear.', 'Finish one started thing.', 'Start another hobby.', 'Finish one thing you started and set aside.', 'Unfinished projects quietly weigh on you. Completing one brings relief and a real sense of progress.'),
  ('cat', 18, 'You show affection on your own schedule. Today, try theirs.', 'Show up when they ask.', 'Make them wait for it.', 'Show up the next time someone asks for you.', 'Affection lands best when it fits the other person''s needs. Showing up when asked builds deep trust.'),
  ('cat', 19, 'Being low-maintenance is great. Being low-communication isn''t.', 'Say what you need.', 'Expect mind reading.', 'Tell one person clearly what you need from them.', 'People can''t meet needs they don''t know about. Saying it plainly saves you both frustration.'),
  ('cat', 20, 'You see through the nonsense. Say it with tact.', 'Be honest and kind.', 'Be honest and cold.', 'Say one honest thing kindly instead of bluntly.', 'The same truth lands very differently depending on tone. Kindness makes people more open to hearing it.'),
  ('cat', 21, 'Today, don''t play hard to get. Play easy to reach.', 'Answer on the first try.', 'Leave them on read.', 'Reply to messages today on the first try.', 'Quick replies show you care and keep plans moving. Playing hard to get mostly just makes things confusing.'),
  ('cat', 22, 'You''re a great observer. Be a participant for one hour.', 'Join in instead of watching.', 'Narrate from the side.', 'Join in for one hour instead of watching from the side.', 'Taking part builds connection in a way observing can''t. People remember who joined in, not who watched.'),
  ('cat', 23, 'Your standards are high. Make sure your effort matches them.', 'Do the thing properly.', 'Critique without helping.', 'Do one task properly before judging others'' work.', 'High standards are easier to respect when you meet them yourself. Doing the work also earns you a say.'),
  ('cat', 24, 'You don''t chase. Fine. But you can walk toward.', 'Make the first move.', 'Wait for perfect timing.', 'Make the first move with someone you want to know.', 'Most people wait to be approached. Taking a small step toward them often gets a warm response.'),
  ('cat', 25, 'A clean space, a clear head. Start with the space.', 'Tidy one corner.', 'Tidy the whole house.', 'Tidy one corner of your space for ten minutes.', 'A tidier space reduces mental clutter. Starting small makes it easy, and the calm spreads.'),
  ('cat', 26, 'You can be independent and still ask for directions.', 'Ask for help early.', 'Get lost out of pride.', 'Ask for help early on something you''re stuck on.', 'Asking early saves time and frustration. Most people are glad to help and think better of you for asking.'),
  ('cat', 27, 'Your curiosity wants a new topic. Feed it something useful.', 'Learn a practical skill.', 'Research celebrity drama.', 'Spend 20 minutes learning a practical skill.', 'Useful skills compound over time. Your curiosity gets fed and your future self gets something out of it.'),
  ('cat', 28, 'Don''t confuse cautious with closed. Open one door today.', 'Accept a new connection.', 'Decline on reflex.', 'Accept one new connection or invite today.', 'Being cautious protects you, but closing off misses good people. One small yes keeps doors open.'),
  ('cat', 29, 'You recharge alone. Just tell people that''s what''s happening.', 'Say "I need a quiet night."', 'Ghost the group.', 'Tell your friends when you need a quiet night.', 'Time alone is healthy. Saying so out loud keeps people from reading your silence as rejection.'),
  ('cat', 30, 'Your timing is excellent. Today, it''s time to speak.', 'Raise the topic.', 'Wait one more week.', 'Bring up the topic you''ve been waiting to raise.', 'Waiting for the perfect moment often means never. Raising it now keeps it small and easier to solve.'),
  ('cat', 31, 'You know exactly what you want. Asking for it is the next level.', 'Ask directly.', 'Drop vague hints.', 'Ask directly for one thing you want.', 'Hints are easy to miss or misread. A direct ask is clearer and gets results more often.'),
  ('cat', 32, 'Some people need more than a slow blink. Use your words.', 'Say it out loud.', 'Rely on the look.', 'Say one thing you feel out loud instead of hinting.', 'Looks and gestures are easy to misread. Words remove the guesswork and help people respond.'),
  ('cat', 33, 'You''re not cold, you''re precise. Add one warm sentence anyway.', 'End with something kind.', 'Send only facts.', 'End one message today with a warm sentence.', 'A kind closing line makes even short messages feel friendly. Tone matters as much as the facts.'),
  ('cat', 34, 'Being picky saves time. Being too picky saves you from everything.', 'Lower one bar slightly.', 'Reject on a detail.', 'Give one option you''d normally reject a fair try.', 'Very high standards can filter out good things too. Lowering one bar slightly can lead to a nice surprise.'),
  ('cat', 35, 'Today''s adventure is small and nearby. Go find it.', 'Explore your own street.', 'Wait for a big trip.', 'Explore a street or spot near you that you''ve never visited.', 'Small adventures close to home still bring novelty. You don''t need a big trip to refresh your mind.'),
  ('cat', 36, 'Someone keeps offering affection. Accept it like a person, not a cat.', 'Say thank you.', 'Walk away mid-hug.', 'Say thank you when someone shows you affection.', 'Accepting warmth gracefully makes the other person feel valued. Brushing it off can feel like rejection.'),
  ('cat', 37, 'You keep your cards close. Show one to someone trustworthy.', 'Share one secret plan.', 'Guard everything.', 'Share a plan you''ve kept to yourself with someone you trust.', 'Telling a trusted person about a goal makes it more real. It also builds closeness and support.'),
  ('cat', 38, 'Your independence inspires people. Your sarcasm sometimes doesn''t.', 'Joke gently.', 'Win the roast.', 'Keep your jokes gentle today.', 'Sharp sarcasm can sting even when meant as fun. Gentle humor keeps people laughing with you, not around you.'),
  ('cat', 39, 'Today, be curious about a person, not just a topic.', 'Ask a follow-up question.', 'Change the subject to you.', 'Ask one follow-up question in a conversation.', 'Follow-up questions show you''re listening. People like those who ask them more than those who talk well.'),
  ('cat', 40, 'You don''t need a crowd to have fun. You might need a plan.', 'Plan a solo treat.', 'Drift all day.', 'Plan one small treat for yourself today.', 'A planned treat gives you something to look forward to. Anticipation is half the fun of a good moment.'),
  ('cat', 41, 'Your judgment is sharp. Make sure your facts are too.', 'Check before you comment.', 'Assume the worst.', 'Check one fact before you comment on something.', 'Quick judgments feel confident but can be wrong. A short check protects your reputation and avoids conflicts.'),
  ('cat', 42, 'You''re great at boundaries. Make sure there''s a door in the wall.', 'Let one person in.', 'Raise the wall higher.', 'Let one person a little closer today.', 'Boundaries keep you safe, but connection needs openings. Letting someone in builds trust over time.'),
  ('cat', 43, 'Not everything needs your approval. Some things just need your presence.', 'Show up without critique.', 'Grade the experience.', 'Show up to one thing without commenting on it.', 'Being present is often what people want most. Holding back critique lets them enjoy your company.'),
  ('cat', 44, 'Being adaptable means you can handle a change of plans. Prove it.', 'Roll with the switch.', 'Sulk about it.', 'Roll with one change of plans without complaining.', 'Adapting smoothly makes things easier for everyone. Accepting what you can''t change saves your energy.'),
  ('cat', 45, 'You''re interesting. Let people find that out without an interview.', 'Volunteer a fun fact.', 'Make them earn it.', 'Share one fun fact about yourself without being asked.', 'Volunteering something about you makes people feel welcome. It signals you want to connect.'),
  ('cat', 46, 'Today, finish the conversation you walked away from.', 'Go back and close it.', 'Pretend it never happened.', 'Go back and finish one conversation you walked away from.', 'Unresolved talks linger in both minds. Closing one brings relief and often clears up a misunderstanding.'),
  ('cat', 47, 'The sunbeam moves. So should you, at least once today.', 'Change your scenery.', 'Stay glued to one spot.', 'Change your setting for part of the day.', 'A new environment can refresh your focus and mood. Even moving to another room helps.'),
  ('cat', 48, 'You play it cool. Someone needs you to play it warm.', 'Show you care.', 'Act unbothered.', 'Tell one person you care, in plain words.', 'Playing it cool can look like indifference. A warm word reassures people who need to hear it.'),
  ('cat', 49, 'You have nine lives, but only one inbox. Clean it.', 'Archive the clutter.', 'Ignore the red badge.', 'Archive or delete old emails for ten minutes.', 'A cleaner inbox reduces stress and makes important messages easier to spot. Ten minutes is enough to feel it.'),
  ('cat', 50, 'Your selective attention is a skill. Point it at what matters.', 'Focus on one priority.', 'Chase every shiny thing.', 'Pick one priority and give it your best hour.', 'Your focus works best on one thing at a time. Chasing everything spreads it too thin to finish anything.'),
