  ('unicorn', 57, 'Magic is in the follow-through. Follow through on one thing.', 'Complete it.', 'Re-imagine it.', 'Complete one thing you''ve been reimagining.', 'Endless reimagining stops things from being finished. Completing one brings satisfaction and real results.'),
  ('unicorn', 58, 'You see beauty everywhere. Point one out to a friend.', 'Share a beautiful thing.', 'Keep it private.', 'Show a friend one beautiful thing you noticed.', 'Pointing out beauty shares your joy. It also helps your friend notice more good things around them.'),
  ('unicorn', 59, 'Today, be visionary and humble at the same time.', 'Ask for input.', 'Assume you know.', 'Ask someone for input on one idea.', 'Big visions get stronger with input. Asking others shows humility and helps them feel part of it.'),
  ('unicorn', 60, 'You''re rare. Act like it: kind, creative and on time.', 'Be on time.', 'Be fashionably late.', 'Be on time and kind to everyone today.', 'Rare people combine creativity with reliability. Kindness and timing build trust.'),
  ('wolf', 1, 'Your pack is lucky to have you. Tell them, then let them tell you back.', 'Say "I''ve got you."', 'Assume they know.', 'Tell one friend "I''ve got you" and mean it.', 'People can''t see loyalty until it''s said. Hearing it out loud makes them feel safe and invites the same back.'),
  ('wolf', 2, 'Loyalty is your strength. Suspicion of every newcomer is your tax.', 'Welcome someone new.', 'Interrogate them.', 'Welcome one new person warmly today.', 'Newcomers decide fast whether they belong. A warm hello costs little and can turn a stranger into a friend.'),
  ('wolf', 3, 'You protect your people fiercely. Protect your own energy too.', 'Rest after helping.', 'Run on empty.', 'Rest for a while after helping someone today.', 'Helping uses real energy. Recovering after it lets you keep helping without burning out.'),
  ('wolf', 4, 'The pack can survive one evening without you.', 'Take a night off.', 'Check the group chat hourly.', 'Take one evening off from the group chat.', 'Your group can manage without you for a night. Stepping away helps you recharge and come back fresh.'),
  ('wolf', 5, 'Strong-willed is great. Today, bend a little.', 'Compromise once.', 'Win the standoff.', 'Meet someone halfway on one disagreement.', 'Strong will is useful, but small compromises keep relationships strong. Both sides feel heard.'),
  ('wolf', 6, 'You work best in a team. Today, ask the team for help.', 'Ask for backup.', 'Do it alone.', 'Ask your team for help with one task.', 'Asking for backup shares the load and builds trust. Teams grow stronger when everyone pitches in.'),
  ('wolf', 7, 'Outsiders aren''t threats. Some are future pack members.', 'Give a newcomer a chance.', 'Judge on sight.', 'Give one newcomer a real chance today.', 'First impressions can be wrong. Giving people time often reveals great new connections.'),
  ('wolf', 8, 'Your loyalty is legendary. Make sure it goes to people who earn it.', 'Invest in mutual friends.', 'Chase one-sided loyalty.', 'Spend time with a friend who gives back as much as you do.', 'Loyalty works best when it''s mutual. Investing in two-way friendships protects your energy.'),
  ('wolf', 9, 'Today, howl a little. Say how you feel out loud.', 'Express your feelings.', 'Bottle them up.', 'Say how you feel out loud to someone close.', 'Holding feelings in makes them heavier. Saying them helps people support you.'),
  ('wolf', 10, 'You''re resilient. You don''t need to prove it every day.', 'Take it easy.', 'Push to prove it.', 'Take one task easy today.', 'Resilience doesn''t need daily proof. Easing off now helps you stay strong for when it counts.'),
  ('wolf', 11, 'Protective is good. Overprotective is a leash.', 'Let them choose.', 'Decide for them.', 'Let someone make their own choice today.', 'Protecting people is kind, but overprotecting limits their growth. Trust shows respect.'),
  ('wolf', 12, 'Being apart from your pack feels weird. It''s fine. Enjoy solo time.', 'Do something alone.', 'Feel lost alone.', 'Do one activity alone and enjoy it.', 'Time alone helps you recharge. It also reminds you that you''re strong on your own.'),
  ('wolf', 13, 'Your group instincts are sharp. Use them to include the quiet one.', 'Pull them in.', 'Stick to the core.', 'Pull the quietest person into the group.', 'Feeling included means a lot. Your group instincts can help someone feel they belong.'),
  ('wolf', 14, 'Today, be the wolf who listens before leading.', 'Listen first.', 'Lead first.', 'Listen to everyone before you lead.', 'Listening first builds trust and gives you more ideas. People follow leaders who hear them.'),
  ('wolf', 15, 'You''d do anything for your friends. Do one thing for you.', 'Treat yourself.', 'Only serve others.', 'Do one thing just for yourself today.', 'Caring for yourself keeps you able to care for others. You matter too.'),
  ('wolf', 16, 'Teamwork makes the dream work. Delegation makes it happen faster.', 'Delegate a task.', 'Do it all.', 'Hand off one task to someone else.', 'Doing everything yourself slows the whole group. Handing off one task saves time and shows you trust them.'),
  ('wolf', 17, 'You''re suspicious of change. Today, try one new thing.', 'Say yes to new.', 'Stick to the known.', 'Say yes to one new thing today.', 'New experiences keep your mind flexible. Small changes reduce fear of bigger ones.'),
  ('wolf', 18, 'Your strength is quiet and steady. Let people lean on it gently.', 'Offer support.', 'Wait to be asked.', 'Offer support to someone who seems to need it.', 'People don''t always ask for help. A gentle offer shows they can lean on you.'),
  ('wolf', 19, 'Today, celebrate a pack member''s win.', 'Throw a shoutout.', 'Stay quiet.', 'Celebrate one friend''s win publicly.', 'Shared celebration strengthens bonds. It shows you''re proud of your group.'),
  ('wolf', 20, 'Being strong-willed helps you finish. Being flexible helps you win.', 'Adapt the plan.', 'Force the plan.', 'Adapt one plan instead of forcing it.', 'Flexibility helps you reach goals more easily. Forcing plans can create stress.'),
  ('wolf', 21, 'The lone-wolf phase is over. Rejoin the group.', 'Reach out to the group.', 'Isolate.', 'Reach out to your group today.', 'Isolation can feel safe but lonely. Reconnecting brings support and joy.'),
  ('wolf', 22, 'Your loyalty makes people feel safe. Make yourself feel safe too.', 'Set a boundary.', 'Absorb it all.', 'Set one boundary to protect your energy.', 'Being everyone''s safe place can leave you with none. A clear boundary keeps your loyalty from wearing you down.'),
  ('wolf', 23, 'Today, the pack needs a plan. You''re the one to make it.', 'Organize something.', 'Wait for someone else.', 'Organize one plan for your group.', 'Groups often wait for someone to decide. A simple plan from you gets everyone together faster.'),
  ('wolf', 24, 'You defend your friends. Defend your time too.', 'Say no to one request.', 'Overcommit.', 'Say no to one request that drains you.', 'Protecting your time keeps you strong. It helps you show up fully when it matters.'),
  ('wolf', 25, 'Not every outsider wants to break the pack. Some want to join it.', 'Invite someone in.', 'Keep the circle closed.', 'Invite someone new into your circle.', 'Closed circles can grow stale. A new person brings fresh energy and often becomes a loyal friend.'),
  ('wolf', 26, 'You''re resilient. Help someone else be resilient today.', 'Encourage a friend.', 'Tell them to toughen up.', 'Encourage a friend who''s struggling.', 'Encouragement helps people believe they can get through it. Your steady support can be the push they need.'),
  ('wolf', 27, 'Today, a heartfelt message beats a quick emoji.', 'Write a real message.', 'Send a thumbs-up.', 'Send one real, heartfelt message today.', 'Thoughtful messages strengthen connections. They show you care more than an emoji can.'),
  ('wolf', 28, 'Strong will is a gift. Stubbornness is the wrapping. Unwrap it.', 'Stay open-minded.', 'Hold your ground blindly.', 'Stay open-minded on one opinion today.', 'Holding on too tightly to an opinion can block better ideas. Staying open makes your strong will smarter.'),
  ('wolf', 29, 'Your pack trusts your judgment. Make it a thoughtful one.', 'Think it through.', 'Decide on instinct.', 'Think one decision through before acting.', 'Others trust your judgment. Thinking it through helps you choose wisely.'),
  ('wolf', 30, 'Today, show your soft side. The pack will love it.', 'Be affectionate.', 'Stay tough.', 'Show affection to someone close.', 'Friends may not see the warmth behind your strength. Showing affection makes them feel truly valued.'),
  ('wolf', 31, 'You''re protective. Let someone protect you for once.', 'Accept their help.', 'Refuse the help.', 'Accept help from someone today.', 'Letting others protect you builds trust. It makes relationships balanced.'),
  ('wolf', 32, 'Being part of a pack doesn''t mean losing yourself.', 'Keep your own opinion.', 'Go with the group.', 'Share your own opinion in one group discussion.', 'Going along with the group can hide your own view. Sharing it adds value and keeps you true to yourself.'),
  ('wolf', 33, 'Today, loyalty to yourself comes first.', 'Honor your needs.', 'Ignore them for others.', 'Put your own needs first once today.', 'Loyalty to yourself keeps you strong. It helps you care for others better.'),
  ('wolf', 34, 'Your group instincts are great. Your solo goals matter too.', 'Work on a personal goal.', 'Only do group stuff.', 'Spend one hour on a personal goal.', 'Your goals matter too. Personal growth makes you a stronger part of the group.'),
  ('wolf', 35, 'You can sense when someone''s left out. Act on it.', 'Include them.', 'Notice and move on.', 'Include someone who''s left out today.', 'Small actions make people feel valued. Including them builds belonging.'),
  ('wolf', 36, 'Today, trust a newcomer with a small task.', 'Give them a chance.', 'Micromanage them.', 'Trust a newcomer with one small task.', 'Trust grows when people get a chance to prove themselves. A small task is a low-risk way to start.'),
  ('wolf', 37, 'The pack is strong because everyone contributes. Let them.', 'Share the work.', 'Carry it all.', 'Share one task so others can contribute.', 'Carrying everything yourself leaves others feeling useless. Sharing work makes the whole group stronger.'),
  ('wolf', 38, 'You''re a great teammate. Be a great friend to yourself today.', 'Be kind to yourself.', 'Be your harshest critic.', 'Be kind to yourself about one mistake.', 'You''d forgive a friend for this mistake. Treating yourself the same way helps you learn instead of spiral.'),
  ('wolf', 39, 'Today, take the lead in a gentle way.', 'Guide softly.', 'Command loudly.', 'Lead one moment gently instead of loudly.', 'Gentle leadership builds trust. People follow kindness more willingly.'),
  ('wolf', 40, 'Your strength inspires. Your vulnerability connects. Show both.', 'Share a struggle.', 'Hide it.', 'Share one struggle with someone you trust.', 'Vulnerability builds deep connection. It shows strength, not weakness.'),
  ('wolf', 41, 'Being suspicious protected you once. It might not be needed now.', 'Lower your guard.', 'Raise it higher.', 'Lower your guard with one person today.', 'Old caution may no longer be needed. Openness can bring good surprises.'),
  ('wolf', 42, 'Today, call a pack member you haven''t heard from.', 'Reach out.', 'Wait for them.', 'Call a friend you haven''t heard from.', 'Friends who go quiet often wonder if anyone notices. A call shows them they still matter to you.'),
  ('wolf', 43, 'You''re loyal to the end. Make sure the end isn''t burnout.', 'Rest before you''re done.', 'Run until empty.', 'Rest before you feel completely drained.', 'Loyalty is easier to keep up when you''re rested. Stopping before you''re drained keeps you there for the long run.'),
  ('wolf', 44, 'Team spirit is your thing. Bring it to a solo task.', 'Cheer yourself on.', 'Drag through it.', 'Cheer yourself on during one solo task.', 'Team spirit works on solo tasks too. Encouraging yourself out loud can boost focus and motivation.'),
  ('wolf', 45, 'Today, the strongest wolf is the one who asks for help.', 'Ask for support.', 'Pretend you''re fine.', 'Ask someone for support today.', 'Asking for support shows trust, not weakness. It gives your people the chance to show up for you.'),
  ('wolf', 46, 'You defend your opinions fiercely. Hear a different one today.', 'Listen openly.', 'Argue back.', 'Listen openly to one different opinion.', 'Listening openly doesn''t mean giving in. It helps you understand others and sharpens your own view.'),
  ('wolf', 47, 'Your pack is your home. Make your home a nice place tonight.', 'Tidy and relax.', 'Stay out late.', 'Tidy your home and relax tonight.', 'Your home is where you recharge. A tidy, calm space makes it easier to rest and feel safe.'),
  ('wolf', 48, 'Today, change isn''t a threat. It''s a new trail.', 'Explore the new path.', 'Resist it.', 'Try one new path or routine today.', 'Change feels risky, but small new paths build flexibility. They make bigger changes feel less scary.'),
  ('wolf', 49, 'You''re steady in storms. Be steady in small things too.', 'Handle details calmly.', 'Stress about little stuff.', 'Handle one small detail calmly.', 'Staying calm in small things makes you steadier overall. It also keeps little stresses from piling up.'),
  ('wolf', 50, 'Loyalty includes honesty. Tell a friend the truth kindly.', 'Be honest kindly.', 'Stay quiet to keep peace.', 'Tell one friend a truth kindly.', 'Honesty is a form of loyalty. A truth said kindly helps a friend grow and shows you really care.'),
  ('wolf', 51, 'Today, make a new friend without vetting them for a month.', 'Be open fast.', 'Run a background check.', 'Be open to one new friend today.', 'Long tests can scare off good people. A little openness gives new friendships a chance to grow.'),
  ('wolf', 52, 'Your pack loves you for you. No need to perform strength.', 'Be real.', 'Act tough.', 'Be your real self with your group.', 'Acting tough takes energy and keeps people at a distance. Being real lets friends know the true you.'),
  ('wolf', 53, 'Today, guard your peace like you guard your people.', 'Protect your calm.', 'Join every fight.', 'Protect your calm in one tense moment.', 'Joining every fight wears down your peace. Guarding your calm keeps you steady for what matters most.'),
  ('wolf', 54, 'You lead well in groups. Today, follow well too.', 'Follow someone''s lead.', 'Take over.', 'Follow someone else''s lead once today.', 'Following well shows trust and builds teamwork. It also gives others the chance to lead and grow.'),
  ('wolf', 55, 'Being strong-willed means finishing what you start. Finish one thing.', 'Complete a task.', 'Start a new one.', 'Finish one task you started.', 'Unfinished tasks quietly drain energy. Completing one gives you momentum and a real sense of progress.'),
  ('wolf', 56, 'Today, your loyalty is noticed. Let it be enough.', 'Trust it''s seen.', 'Demand recognition.', 'Let one act of loyalty be enough today.', 'Needing recognition can turn loyalty into a burden. Trusting it''s seen brings more peace than demanding it.'),
  ('wolf', 57, 'The pack thrives on shared meals and stories. Plan one.', 'Plan a group dinner.', 'Eat alone at your desk.', 'Plan a shared meal with friends.', 'Shared meals build connection and create stories people remember. They''re a simple way to bring everyone together.'),
  ('wolf', 58, 'You protect others well. Protect a little time for your dreams.', 'Work on your dream.', 'Only work for others.', 'Spend one hour on your own dream.', 'Helping others is your strength, but your dreams need time too. One focused hour keeps them alive.'),
  ('wolf', 59, 'Today, let someone outside your circle surprise you.', 'Stay curious.', 'Stay guarded.', 'Stay curious about someone new today.', 'Curiosity opens doors to new connections. It keeps your world growing.'),
  ('wolf', 60, 'You''re the heart of your pack. Hearts need rest too.', 'Slow down tonight.', 'Keep going.', 'Slow down tonight and rest.', 'Even the heart of the group needs rest. Slowing down keeps you strong.')
) as v (animal, day_index, message, do_text, dont_text, action_text, action_why)
join public.animal_auras a on lower(btrim(a.name)) = v.animal
where m.aura_id = a.id
  and m.season = 1
  and m.day_index = v.day_index;

-- Every animal must be found, or the seed silently skips its rows.
do $$
declare
  v_missing text;
begin
  select string_agg(v.animal, ', ') into v_missing
  from unnest(array['bear', 'cat', 'deer', 'dolphin', 'eagle', 'elephant', 'fox', 'lion', 'otter', 'owl', 'parrot', 'peacock', 'snake', 'unicorn', 'wolf']) as v (animal)
  where not exists (select 1 from public.animal_auras a where lower(btrim(a.name)) = v.animal);
  if v_missing is not null then
    raise exception 'daily aura seed: animals not found in animal_auras: %', v_missing;
  end if;
end $$;

do $$
declare
  v_count integer;
begin
  select count(*) into v_count
  from public.daily_aura_messages m
  join public.animal_auras a on a.id = m.aura_id
  where m.season = 1
    and m.day_index <= 60
    and lower(btrim(a.name)) = any (array['bear', 'cat', 'deer', 'dolphin', 'eagle', 'elephant', 'fox', 'lion', 'otter', 'owl', 'parrot', 'peacock', 'snake', 'unicorn', 'wolf'])
    and m.message is not null and m.do_text is not null and m.dont_text is not null and m.action_text is not null and m.action_why is not null;
  if v_count <> 900 then
    raise exception 'daily aura update: % of 900 rows found for season 1 (seed them first)', v_count;
  end if;
end $$;

commit;
